<x-filament-panels::page><div class="space-y-6" x-data="titanGoSafety({helpEndpoint:@js($helpEndpoint),unsafeSiteEndpoint:@js($unsafeSiteEndpoint)})"><section class="rounded-3xl border border-red-200 bg-red-50 p-5 shadow-sm dark:border-red-900 dark:bg-red-950/30"><p class="text-sm font-semibold uppercase tracking-wide text-red-700 dark:text-red-300">Safety</p><h2 class="mt-1 text-2xl font-black text-red-950 dark:text-red-100">Need help on site?</h2><p class="mt-2 text-sm text-red-800 dark:text-red-200">Use these actions for urgent help, unsafe-site reporting, or lone-worker check-ins.</p><div class="mt-5 grid gap-3 sm:grid-cols-3"><button type="button" @click="sendHelp" class="rounded-2xl bg-red-600 px-4 py-4 text-sm font-bold text-white shadow-sm">Request help now</button><button type="button" @click="unsafeSite" class="rounded-2xl bg-gray-950 px-4 py-4 text-sm font-bold text-white shadow-sm dark:bg-white dark:text-gray-950">Report unsafe site</button><button type="button" @click="checkIn" class="rounded-2xl border border-red-200 bg-white px-4 py-4 text-sm font-bold text-red-700 shadow-sm dark:border-red-800 dark:bg-red-950/20 dark:text-red-200">I am safe</button></div><div class="mt-4 rounded-2xl bg-white/70 p-4 text-sm font-semibold text-red-900 dark:bg-red-950/30 dark:text-red-100" x-show="message" x-text="message"></div></section></div><script>function titanGoSafety(c){return{...c,message:'',csrf(){return document.querySelector('meta[name="csrf-token"]')?.content||''},async post(u,p){const r=await fetch(u,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':this.csrf()},body:JSON.stringify(p)});return r.json()},async sendHelp(){this.message='Sending help request...';const d=await this.post(this.helpEndpoint,{type:'help',source:'titango_safety'});this.message=d.message||'Help request sent.'},async unsafeSite(){this.message='Logging unsafe-site report...';const d=await this.post(this.unsafeSiteEndpoint,{type:'unsafe_site',source:'titango_safety'});this.message=d.message||'Unsafe-site report logged.'},async checkIn(){this.message='Safe check-in recorded.'}}}</script></x-filament-panels::page>
